changeSet.sql:
ALTER TABLE invoice_document DROP CONSTRAINT ck_invoice_document_source_format;
UPDATE invoice_document
SET source_format = 'UBL'
WHERE source_format = 'XRECHNUNG_UBL';
UPDATE invoice_document
SET source_format = 'CII'
WHERE source_format = 'XRECHNUNG_CII';
ALTER TABLE invoice_document
    ADD CONSTRAINT ck_invoice_document_source_format
        CHECK (source_format IN ('UBL', 'CII', 'ZUGFERD', 'PDF', 'UNKNOWN'));

rollback.sql:
ALTER TABLE invoice_document DROP CONSTRAINT ck_invoice_document_source_format;
UPDATE invoice_document SET source_format = 'XRECHNUNG_UBL' WHERE source_format = 'UBL';
UPDATE invoice_document SET source_format = 'XRECHNUNG_CII' WHERE source_format = 'CII';
ALTER TABLE invoice_document ADD CONSTRAINT ck_invoice_document_source_format
CHECK (source_format IN ('XRECHNUNG_UBL', 'XRECHNUNG_CII', 'ZUGFERD', 'PDF', 'UNKNOWN'));
